var s={en:`A broker has 1,000,000 queued events. Consumers process 600/s while 800/s arrive. Per-order event ordering must remain correct.`,ua:`У брокері 1 000 000 подій. Споживачі обробляють 600/с, а надходить 800/с. Порядок подій одного замовлення має зберегтися.`};var a={en:[`Calculate the net throughput deficit and needed processing capacity.`,`Choose partition keys and scale consumers without breaking per-order order.`,`Define poison-message isolation, lag SLO and catch-up experiment.`],ua:[`Обчисли дефіцит продуктивності та потрібну потужність.`,`Обери ключ партиціювання й масштабуй без порушення порядку.`,`Визнач ізоляцію проблемних подій, SLO черги й тест надолуження.`]};var n=[{en:`Processing capacity must exceed sustained arrivals to drain backlog.`,ua:`Для спорожнення черги обробка має перевищити постійне надходження.`},{en:`Per-order event ordering is explicitly preserved or reconciled.`,ua:`Порядок подій замовлення зберігається або узгоджується.`}];var i={scenario:s,tasks:a,checks:n};export{n as checks,i as default,s as scenario,a as tasks};